<?php
namespace App\Services;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CcsCashierRules{
public const ACTIONS=['discount'=>'Discounts','old_special_plate'=>'Old / special plates','mileage_correction'=>'Mileage corrections','payment_reversal'=>'Payment-entry corrections','invoice_cancel'=>'Invoice cancellation / full refund'];
public function get():array{$saved=app(CcsAdministration::class)->setting('cashier_rules_v107',[]);$out=[];foreach(self::ACTIONS as $k=>$label)$out[$k]=['allowed'=>(bool)($saved[$k]['allowed']??true),'approval'=>(bool)($saved[$k]['approval']??false)];return $out;}
public function check(Request $r,string $kind):bool{if(app(CcsHumanRules::class)->owner($r->user()))return false;abort_unless(($r->user()->ccs_active??false)&&app(CcsAdministration::class)->role($r->user())==='cashier',403);$key=in_array($kind,['draft_discount','walk_in_discount'],true)?'discount':$kind;$p=$this->get()[$key]??['allowed'=>false,'approval'=>true];if(!$p['allowed'])app(CcsHumanRules::class)->fail('rules','Owner has disabled this cashier action: '.(self::ACTIONS[$key]??$key).'.');if(!$p['approval'])$r->validate(['rules_confirm'=>'required|accepted'],['rules_confirm.required'=>'Review the warning and confirm these changes before saving.']);return $p['approval'];}
public function save(Request $r):void{abort_unless(app(CcsHumanRules::class)->owner($r->user()),403);$rules=[];foreach(self::ACTIONS as $k=>$label){$rules['policy.'.$k.'.allowed']='required|boolean';$rules['policy.'.$k.'.approval']='required|boolean';}$r->validate($rules);$new=[];foreach(self::ACTIONS as $k=>$label)$new[$k]=['allowed'=>$r->boolean('policy.'.$k.'.allowed'),'approval'=>$r->boolean('policy.'.$k.'.approval')];DB::transaction(function()use($r,$new){app(CcsHumanRules::class)->lock();$old=$this->get();DB::table('ccs_system_settings')->updateOrInsert(['key'=>'cashier_rules_v107'],['value'=>json_encode($new),'created_at'=>now(),'updated_at'=>now()]);app(CcsAdministration::class)->audit($r->user()->id,'cashier_rules_changed','settings',null,['before'=>$old,'after'=>$new]);});}
}
